<dialog id="coupon-{{ $item->id??'new' }}" class="editor-dialog"><div class="dialog-heading"><h2>{{ $item?'Edit discount code':'A little extra joy' }}</h2><button data-close aria-label="Close coupon editor">×</button></div><form method="post" action="/admin/coupons{{ $item?'/'.$item->id:'' }}" class="dialog-content">@csrf<div class="form-grid"><label>Coupon code<input name="code" value="{{ $item->code??'' }}" pattern="[A-Za-z0-9_-]{2,30}" maxlength="30" required></label><label>Discount type<select name="type"><option value="percentage" @selected(($item->type??'percentage')==='percentage')>Percentage off</option><option value="flat" @selected(($item->type??'')==='flat')>Flat amount off in INR</option></select></label><label>Discount value<input type="number" name="value" min="0.01" max="100000" step="0.01" value="{{ $item?$item->value/100:'' }}" required><small>For percentage use 10 for 10%. For flat use 50 for ₹50.</small></label><label>Minimum item subtotal in INR<input type="number" name="minimum" min="0" step="0.01" value="{{ ($item->minimum??0)/100 }}" required></label><label>Maximum saving in INR<input type="number" name="maximum_discount" min="0.01" step="0.01" value="{{ isset($item->maximum_discount)?$item->maximum_discount/100:'' }}"><small>Optional cap, including percentage discounts.</small></label><label>Total usage limit<input type="number" name="usage_limit" min="1" step="1" value="{{ $item->usage_limit??'' }}"><small>Leave empty for unlimited uses.</small></label><label>Usage limit per customer email<input type="number" name="per_customer_limit" min="1" step="1" value="{{ $item->per_customer_limit??'' }}"><small>Leave empty for unlimited uses.</small></label><label>Starts at in IST<input type="datetime-local" name="starts_at" value="{{ !empty($item->starts_at)?\Carbon\Carbon::parse($item->starts_at)->format('Y-m-d\TH:i'):'' }}"></label><label>Ends at in IST<input type="datetime-local" name="ends_at" value="{{ !empty($item->ends_at)?\Carbon\Carbon::parse($item->ends_at)->format('Y-m-d\TH:i'):'' }}"></label><label class="checkbox full"><input type="checkbox" name="active" value="1" @checked($item->active??true)> Active and available at checkout</label></div><button class="button button-blue">Save coupon</button></form>@if($item)<form method="post" action="/admin/coupons/{{ $item->id }}/status" class="dialog-archive">@csrf<input type="hidden" name="active" value="{{ $item->active?0:1 }}"><button class="text-link">{{ $item->active?'Pause this coupon':'Activate this coupon' }}</button></form>@endif</dialog>
